def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    moves = []
    for c in sorted(set(g.flatten().tolist())):
        if c == bg or c == 8:
            continue
        cells = list(zip(*np.where(g == c)))
        y0, x0, y1, x1 = bbox(cells)
        dy = dx = 0
        for (cy, cx) in [(y0, x0), (y0, x1), (y1, x0), (y1, x1)]:
            if g[cy, cx] == 8:
                dy = -1 if cy == y0 else 1
                dx = -1 if cx == x0 else 1
                break
        moves.append((c, y0, x0, y1, x1, dy, dx))
    out = np.full_like(g, bg)
    emit(out.copy(), "Erase every rectangle and its 8 corner marker, leaving only background.")
    for c, y0, x0, y1, x1, dy, dx in moves:
        for y in range(y0 + dy, y1 + dy + 1):
            for x in range(x0 + dx, x1 + dx + 1):
                if 0 <= y < H and 0 <= x < W:
                    out[y, x] = c
    emit(out.copy(), "Repaint each rectangle solid, shifted one step diagonally toward the corner its 8 marked.")
    return out
